1	import { describe, it, expect } from "vitest";
2	import { run } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quoting: base price list (new customer, first contract: +10 %, +5 G fee) ---
6	  it("quotes a sword for a brand-new customer — 100 * 1.1 + 5 = 115 G", () => {
7	    const scenario = {
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [
10	        {
11	          op: "quote",
12	          items: [
13	            { type: "sword", material: "steel", enchantment: 3, cursed: false },
14	          ],
15	        },
16	      ],
17	    };
18	
19	    expect(run(scenario)).toEqual({ results: [{ premium: 115 }] });
20	  });
21	  it.todo("quotes an amulet for a brand-new customer — 60 * 1.1 + 5 = 71 G");
22	  it.todo("quotes a staff for a brand-new customer — 80 * 1.1 + 5 = 93 G");
23	  it.todo("quotes a potion for a brand-new customer — 40 * 1.1 + 5 = 49 G");
24	  it.todo("quotes a single rune component — 25 * 1.1 + 5 = 33 G (rounded up from 32.5)");
25	  it.todo("quotes a single moonstone component — 25 * 1.1 + 5 = 33 G");
26	  it.todo("sums base premiums of several main items — sword + potion = 140 * 1.1 + 5 = 159 G");
27	
28	  // --- Quoting: component building blocks ---
29	  it.todo("charges 60 G for a building block of 3 alike components instead of 75 G — 60 * 1.1 + 5 = 71 G");
30	  it.todo("charges block price plus single price for 4 alike components — (60 + 25) * 1.1 + 5 = 98.5 -> 99 G");
31	  it.todo("charges two block prices for 6 alike components — 120 * 1.1 + 5 = 137 G");
32	  it.todo("does not form a block from unlike components — 2 runes + 1 moonstone = 75 * 1.1 + 5 = 87.5 -> 88 G");
33	
34	  // --- Quoting: risk surcharges ---
35	  it.todo("adds a 50 % risk surcharge for a cursed item — 100 * 1.5 * 1.1 + 5 = 170 G");
36	  it.todo("adds a 30 % risk surcharge for enchantment level 5 — 100 * 1.3 * 1.1 + 5 = 148 G");
37	  it.todo("adds no enchantment surcharge below level 5 — enchantment 4 sword = 115 G");
38	  it.todo("stacks the cursed and high-enchantment surcharges on the same item — 100 * 1.5 * 1.3 * 1.1 + 5 = 219.5 -> 220 G");
39	  it.todo("applies surcharges per item, not to the whole quote — cursed sword + plain potion = (150 + 40) * 1.1 + 5 = 214 G");
40	
41	  // --- Quoting: customer modifiers ---
42	  it.todo("grants a 20 % loyalty discount at 2 years with MHPCO — 100 * 1.1 * 0.8 + 5 = 93 G");
43	  it.todo("grants no loyalty discount below 2 years with MHPCO — 1 year sword = 115 G");
44	  it.todo("applies a 15 % discount to the second contract instead of the 10 % first-insurance surcharge — 100 * 0.85 + 5 = 90 G");
45	  it.todo("applies the 15 % discount to every contract after the first — third contract sword = 90 G");
46	  it.todo("combines the loyalty discount with the repeat-contract discount — 100 * 0.8 * 0.85 + 5 = 73 G");
47	
48	  // --- Claims: basics ---
49	  it.todo("pays a damage minus the 100 G deductible — 200 G damage to an amulet pays 100 G");
50	  it.todo("pays nothing when the damage does not exceed the deductible — 100 G damage pays 0 G");
51	  it.todo("never pays a negative amount — 40 G damage pays 0 G");
52	  it.todo("applies one deductible per incident, not per damaged item — two 200 G damages pay 300 G");
53	  it.todo("reports the remaining cap after a claim — amulet policy cap 1200, 100 G payout leaves 1100 G");
54	
55	  // --- Claims: reimbursement rates ---
56	  it.todo("reimburses damage to an item with enchantment level 8 at 50 % — 500 G damage pays 250 - 100 = 150 G");
57	  it.todo("reimburses damage to an item with enchantment level 7 in full — 500 G damage pays 400 G");
58	  it.todo("reimburses damage to a dragon-material item in full even at enchantment 8 — 500 G damage pays 400 G");
59	  it.todo("applies the rate per damaged item before the single deductible is subtracted");
60	
61	  // --- Claims: cap ---
62	  it.todo("caps the total payout at twice the insurance sum — amulet policy pays at most 1200 G overall");
63	  it.todo("accumulates payouts across claims against the same policy and reduces the cap each time");
64	  it.todo("pays 0 G once the cap is exhausted and reports a remaining cap of 0 G");
65	  it.todo("keeps caps of separate policies independent");
66	
67	  // --- Multi-step scenarios ---
68	  it.todo("processes a quote followed by two claims on the same policy (schema example 2)");
69	  it.todo("returns one result per step, in step order, with the fields matching each operation");
70	});
