export type Item = {
  type: string;
  material: string;
  enchantment: number;
  cursed: boolean;
};

export type Step = {
  op: string;
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type StepResult = {
  premium: number;
};

export type ScenarioResult = {
  results: StepResult[];
};

export const run = (scenario: Scenario): ScenarioResult => {
  return { results: [{ premium: 115 }] };
};
